```typescript
import { Groq } from '@anthropic-ai/sdk';
import { withRetry } from '@/lib/retry';
import { callGroqJSON } from '@/lib/agents/llm-client';
import { build[Domain]AgentSystemPrompt } from '@/lib/agents/prompts/[domain]';
import { [Domain]AgentResponseSchema, type [Domain]AgentResponse } from '@/lib/agents/schemas/[domain]-agent-response';

export async function parse[Domain]Entry(args: {
  client: Groq;
  text: string;
  nowIso?: string;
  userTz?: string;
  // Add other context params (categories, currency, etc.)
}): Promise<[Domain]AgentResponse> {
  const { client, text, nowIso = new Date().toISOString(), userTz = 'UTC' } = args;

  const system = build[Domain]AgentSystemPrompt({ nowIso, userTz });

  return withRetry(
    () =>
      callGroqJSON<unknown>({
        client,
        model: 'openai/gpt-oss-120b',
        system,
        user: text,
        temperature: 0,
        maxTokens: 256,
      }),
    { attempts: 3, baseMs: 500 }
  ).then((response) => {
    const parsed = [Domain]AgentResponseSchema.safeParse(response);
    if (!parsed.success) {
      throw new Error(
        `[domain]-agent: invalid response — ${parsed.error.message}\nRaw: ${JSON.stringify(response)}`
      );
    }
    return parsed.data;
  });
}
```
- **Mirror**: Copy from `src/lib/agents/task-agent.ts` (lines 1-50) exactly, swap function/schema names
- **Model choice**: gpt-oss-120b for reasoning; gpt-oss-20b only for router
- **Temperature**: Always 0 except digest (0.3)
- **maxTokens**: 256 typical for domain parsers; increase if complex output

