import { useLiveQuery } from 'dexie-react-hooks';
import { db } from '@/lib/dexie';
import type { [Domain]Row } from '@/lib/dexie';

export function use[Domain](userId?: string): [Domain]Row[] {
  return (
    useLiveQuery(
      async () => {
        if (!userId) return [];
        const all = await db.[domain]_entries
          .where('user_id')
          .equals(userId)
          .toArray();
        return all.filter((r) => !r.deleted_at);  // Exclude tombstones
      },
      [userId],
      []
    ) ?? []
  );
}
```
